MATCH (u:User)-[:USES]->(ip:IpAddress)
WHERE u.gender = "Female" AND u.state = "CT" AND EXISTS {
  MATCH (u)-[:WATCHED]->(m:Movie)
  WHERE m.year < 2000
}
RETURN DISTINCT ip.address

MATCH (u1:User)-[:USES]->(ip:IpAddress)
WHERE EXISTS {
  MATCH (u2:User)-[:USES]->(ip)
  WHERE u2.userId <> u1.userId
    AND EXISTS {
      MATCH (u2)-[:WATCHED]->(m:Movie)-[:HAS]->(:Genre {name: "Documentary"})
    }
}
RETURN DISTINCT u1.email

